CREATE TABLE index_manifests (index_kind TEXT NOT NULL CHECK(index_kind IN ('text','image')), version TEXT NOT NULL, model_revision TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('building','ready','retired')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(index_kind,version));
CREATE UNIQUE INDEX active_search_index ON index_manifests(index_kind) WHERE status='ready';
CREATE TABLE text_embeddings (product_id TEXT NOT NULL REFERENCES products(id), model_revision TEXT NOT NULL, index_kind TEXT NOT NULL DEFAULT 'text' CHECK(index_kind='text'), index_version TEXT NOT NULL, source_hash TEXT NOT NULL, vector_data TEXT NOT NULL, PRIMARY KEY(product_id,model_revision,index_version), FOREIGN KEY(index_kind,index_version) REFERENCES index_manifests(index_kind,version));
CREATE TABLE image_embeddings (asset_id TEXT NOT NULL REFERENCES media_assets(id), model_revision TEXT NOT NULL, index_kind TEXT NOT NULL DEFAULT 'image' CHECK(index_kind='image'), index_version TEXT NOT NULL, media_hash TEXT NOT NULL, vector_data TEXT NOT NULL, PRIMARY KEY(asset_id,model_revision,index_version), FOREIGN KEY(index_kind,index_version) REFERENCES index_manifests(index_kind,version));
CREATE TABLE segment_models (model_version TEXT PRIMARY KEY, eps REAL NOT NULL CHECK(eps>0), min_samples INTEGER NOT NULL CHECK(min_samples>=2), feature_schema TEXT NOT NULL, scaler TEXT NOT NULL, core_samples TEXT NOT NULL, cutoff_at TEXT NOT NULL, validation_state TEXT NOT NULL CHECK(validation_state IN ('draft','approved','rejected','retired')), metrics TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX active_segment_model ON segment_models(validation_state) WHERE validation_state='approved';
CREATE TABLE segment_assignments (customer_id TEXT NOT NULL REFERENCES customers(id), model_version TEXT NOT NULL REFERENCES segment_models(model_version), cluster_label INTEGER NOT NULL CHECK(cluster_label>=-1), assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(customer_id,model_version));
